// Concept 03: Hydroelectric Flow - Water to Electricity
// Pure Canvas 2D. Duration: 25 s. Seamless. No external assets or dependencies.
// Encoder export target: 3840 x 2160, 60 fps, 100000000 bits/s (100 Mbps).
// Configure bitrate in the video encoder; drawing code does not set bitrate.

const GE_HYDRO = (() => {
  'use strict';
  const TAU = Math.PI * 2;
  const C = Object.freeze({
    ink: '#192944', blue: '#3568D4', deep: '#244A91', pale: '#E8EFFF',
    ice: '#C6D8FA', white: '#FFFCF5', purple: '#7662C7',
    amber: '#F4B449', coral: '#EE8876', steel: '#A8BCDF'
  });
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const fract = v => v - Math.floor(v);

  function rounded(ctx, x, y, w, h, r = 8) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(ctx, x, y, w, h, fill, r = 8, stroke = C.ink, line = 3.5) {
    rounded(ctx, x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && line > 0) { ctx.lineWidth = line; ctx.strokeStyle = stroke; ctx.stroke(); }
  }
  function line(ctx, points, color = C.ink, width = 3) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke = C.ink, width = 3) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && width > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function bolt(ctx, x, y, scale = 1, color = C.amber) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    ctx.beginPath();
    ctx.moveTo(3, -18); ctx.lineTo(-12, 3); ctx.lineTo(-1, 3);
    ctx.lineTo(-5, 19); ctx.lineTo(13, -5); ctx.lineTo(2, -5);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill();
    ctx.restore();
  }
  function label(ctx, text, x, y, size = 12, color = C.ink) {
    ctx.fillStyle = color;
    ctx.font = '600 ' + size + 'px "Nimbus Sans", Arial, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, x, y);
  }
  function mix(a, b, u) {
    u = clamp(u);
    const ai = parseInt(a.slice(1), 16), bi = parseInt(b.slice(1), 16);
    const r = Math.round((ai >> 16) * (1 - u) + (bi >> 16) * u);
    const g = Math.round(((ai >> 8) & 255) * (1 - u) + ((bi >> 8) & 255) * u);
    const bl = Math.round((ai & 255) * (1 - u) + (bi & 255) * u);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  // Precomputed arc-length tables keep packets moving smoothly around bends.
  function route(points, radius = 15) {
    const commands = [], samples = [];
    function sample(x, y) {
      const last = samples[samples.length - 1];
      const distance = last ? last.d + Math.hypot(x - last.x, y - last.y) : 0;
      samples.push({ x, y, d: distance });
    }
    function to(x, y) { commands.push(['L', x, y]); sample(x, y); }
    commands.push(['M', points[0][0], points[0][1]]);
    sample(points[0][0], points[0][1]);
    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1], b = points[i], c = points[i + 1];
      const before = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const after = Math.hypot(c[0] - b[0], c[1] - b[1]);
      if (before < 0.001 || after < 0.001) continue;
      const r = Math.min(radius, before * 0.4, after * 0.4);
      const ex = b[0] - (b[0] - a[0]) / before * r;
      const ey = b[1] - (b[1] - a[1]) / before * r;
      const ox = b[0] + (c[0] - b[0]) / after * r;
      const oy = b[1] + (c[1] - b[1]) / after * r;
      to(ex, ey);
      commands.push(['Q', b[0], b[1], ox, oy]);
      for (let j = 1; j <= 24; j++) {
        const u = j / 24, v = 1 - u;
        sample(v * v * ex + 2 * v * u * b[0] + u * u * ox,
               v * v * ey + 2 * v * u * b[1] + u * u * oy);
      }
    }
    const end = points[points.length - 1];
    to(end[0], end[1]);
    return { commands, samples, length: samples[samples.length - 1].d };
  }
  function trace(ctx, r) {
    ctx.beginPath();
    for (const cmd of r.commands) {
      if (cmd[0] === 'M') ctx.moveTo(cmd[1], cmd[2]);
      else if (cmd[0] === 'L') ctx.lineTo(cmd[1], cmd[2]);
      else ctx.quadraticCurveTo(cmd[1], cmd[2], cmd[3], cmd[4]);
    }
  }
  function at(r, distance) {
    const a = r.samples;
    let low = 1, high = a.length - 1;
    while (low < high) {
      const middle = (low + high) >> 1;
      if (a[middle].d < distance) low = middle + 1; else high = middle;
    }
    const p = a[low - 1], q = a[low];
    const u = clamp((distance - p.d) / Math.max(0.0001, q.d - p.d));
    return { x: p.x + (q.x - p.x) * u, y: p.y + (q.y - p.y) * u };
  }
  function cable(ctx, r, phase, offset = 0, color = C.amber) {
    trace(ctx, r); ctx.strokeStyle = C.ink; ctx.lineWidth = 13; ctx.stroke();
    trace(ctx, r); ctx.strokeStyle = C.ice; ctx.lineWidth = 7; ctx.stroke();
    // A shared spatial lattice gives every connected cable the same speed.
    // Twenty whole spacing cycles in 25 s preserve the exact loop state.
    const spacing = 78, shift = fract(phase * 20 + offset) * spacing;
    const packetCount = Math.ceil(r.length / spacing);
    for (let i = -1; i <= packetCount; i++) {
      const distance = i * spacing + shift;
      if (distance < 0 || distance > r.length) continue;
      const p = at(r, distance);
      circle(ctx, p.x, p.y, 3.2, color, null, 0);
    }
  }
  function node(ctx, x, y) { circle(ctx, x, y, 8, C.white, C.ink, 3); }
  return { TAU, C, clamp, fract, rounded, box, line, circle, bolt, label, mix, route, cable, node, trace, at };
})();

function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);

  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (width <= 0 || height <= 0 || !Number.isFinite(t)) return;

  const G = GE_HYDRO, C = G.C;
  const phase = (currentScene + sceneProgress) / sceneCount;
  const scale = Math.min(width / 1600, height / 900, minSide / 900);

  const routes = G.routes || (G.routes = {
    penstock: G.route([[428, 427], [550, 427], [686, 575], [790, 575]], 25),
    discharge: G.route([[850, 631], [850, 745], [1054, 745]], 23),
    power: G.route([[1218, 550], [1270, 550], [1270, 570], [1350, 570]], 14)
  });

  ctx.save();
  ctx.setTransform(scale, 0, 0, scale, (width - 1600 * scale) / 2, (height - 900 * scale) / 2);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0;
  ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.setLineDash([]);

  // Opaque flow strokes are clipped by equipment at the attached endpoints.
  function tube(ctx, r, phase, color, width = 24, offset = 0, speedCycles = 20, openEnd = false) {
    const oldCap = ctx.lineCap;
    if (openEnd) ctx.lineCap = 'butt';
    G.trace(ctx, r); ctx.lineWidth = width + 7; ctx.strokeStyle = C.ink; ctx.stroke();
    G.trace(ctx, r); ctx.lineWidth = width; ctx.strokeStyle = color; ctx.stroke();
    ctx.lineCap = oldCap;
    const spacing = 72, shift = G.fract(phase * speedCycles + offset) * spacing;
    const count = Math.ceil(r.length / spacing);
    for (let i = -1; i <= count; i++) {
      const d = i * spacing + shift;
      if (d < 8 || d > r.length - 8) continue;
      const a = G.at(r, d - 5), b = G.at(r, d + 5);
      G.line(ctx, [[a.x, a.y], [b.x, b.y]], C.white, Math.max(3, width * 0.21));
    }
  }
  function rotor(ctx, x, y, radius, phase, bladeCount = 10, tint = C.blue) {
    G.circle(ctx, x, y, radius, C.white, C.ink, 4);
    G.circle(ctx, x, y, radius - 13, C.pale, C.ink, 2.5);
    const theta = G.TAU * phase * 5;
    ctx.save(); ctx.translate(x, y); ctx.rotate(theta);
    for (let i = 0; i < bladeCount; i++) {
      ctx.save(); ctx.rotate(i * G.TAU / bladeCount);
      ctx.beginPath();
      ctx.moveTo(radius * 0.23, -radius * 0.075);
      ctx.quadraticCurveTo(radius * 0.48, -radius * 0.24, radius * 0.70, -radius * 0.16);
      ctx.lineTo(radius * 0.66, radius * 0.025);
      ctx.quadraticCurveTo(radius * 0.44, -radius * 0.01, radius * 0.25, radius * 0.075);
      ctx.closePath(); ctx.fillStyle = tint; ctx.fill();
      ctx.strokeStyle = C.ink; ctx.lineWidth = 1.6; ctx.stroke();
      ctx.restore();
    }
    ctx.restore();
    G.circle(ctx, x, y, radius * 0.22, C.deep, C.ink, 3);
    G.circle(ctx, x, y, radius * 0.075, C.white, null, 0);
    for (let i = 0; i < 8; i++) {
      const a = i * G.TAU / 8;
      G.circle(ctx, x + Math.cos(a) * (radius - 6.5), y + Math.sin(a) * (radius - 6.5), 1.7, C.ink, null, 0);
    }
  }
  function generator(ctx, x, y, w, h, phase) {
    G.box(ctx, x + 18, y + h - 2, 18, 31, C.steel, 4, C.ink, 3);
    G.box(ctx, x + w - 36, y + h - 2, 18, 31, C.steel, 4, C.ink, 3);
    G.box(ctx, x - 9, y + h + 24, w + 18, 12, C.pale, 4, C.ink, 3);
    G.box(ctx, x, y, w, h, C.white, 15, C.ink, 4);
    G.box(ctx, x + 17, y + 18, w - 34, 36, C.deep, 7, C.ink, 2.5);
    G.label(ctx, 'AC', x + w / 2, y + 36, 13, C.white);
    const left = x + 20, top = y + 70;
    for (let i = 0; i < 6; i++) G.box(ctx, left + i * (w - 40) / 6, top, 8, h - 89, C.ice, 3, C.ink, 1.5);
    for (const sx of [x + 9, x + w - 9]) for (const sy of [y + 9, y + h - 9]) G.circle(ctx, sx, sy, 1.7, C.ink, null, 0);
    const q = 0.5 + 0.5 * Math.sin(G.TAU * phase * 5);
    G.circle(ctx, x + w - 24, y + h - 17, 3.5, G.mix(C.steel, C.blue, q), C.ink, 1.2);
  }
  function switchgear(ctx, x, y, w, h, phase) {
    G.box(ctx, x + 13, y + h - 1, 15, 26, C.steel, 3, C.ink, 2.5);
    G.box(ctx, x + w - 28, y + h - 1, 15, 26, C.steel, 3, C.ink, 2.5);
    G.box(ctx, x - 5, y + h + 20, w + 10, 11, C.pale, 4, C.ink, 3);
    G.box(ctx, x, y, w, h, C.white, 12, C.ink, 4);
    G.box(ctx, x + 15, y + 18, w - 30, 48, C.deep, 6, C.ink, 2.5);
    ctx.save(); G.rounded(ctx, x + 21, y + 24, w - 42, 36, 3); ctx.clip();
    ctx.beginPath();
    for (let i = 0; i <= 50; i++) {
      const xx = x + 21 + i / 50 * (w - 42);
      const yy = y + 42 + 8 * Math.sin(G.TAU * (i / 25 - phase * 5));
      if (!i) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
    }
    ctx.lineWidth = 2.5; ctx.strokeStyle = C.white; ctx.stroke(); ctx.restore();
    G.box(ctx, x + 25, y + 83, w - 50, h - 112, C.pale, 7, C.ink, 2.5);
    G.bolt(ctx, x + w / 2, y + 83 + (h - 112) / 2, Math.min(0.9, (h - 112) / 45), C.amber);
    for (let i = 0; i < 3; i++) G.circle(ctx, x + w / 2 - 19 + i * 19, y + h - 15, 3, C.blue, C.ink, 1.2);
  }


  // Reservoir: one closed 2D outline; current marks stay inside its mask.
  function reservoirPath() {
    ctx.beginPath();
    for (let i = 0; i <= 80; i++) {
      const u = i / 80;
      const wave = 5 * Math.pow(Math.sin(Math.PI * u), 2) * Math.sin(G.TAU * (2 * u - phase * 5));
      const x = 116 + 356 * u, y = 352 + wave;
      if (!i) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.lineTo(472, 650); ctx.lineTo(128, 650);
    ctx.quadraticCurveTo(116, 650, 116, 638); ctx.closePath();
  }
  reservoirPath(); ctx.fillStyle = C.pale; ctx.fill();
  ctx.save(); reservoirPath(); ctx.clip();
  ctx.fillStyle = C.ice; ctx.fillRect(112, 533, 365, 125);
  for (let row = 0; row < 4; row++) {
    for (let i = -1; i < 5; i++) {
      const x = 95 + (i + G.fract(phase * 5)) * 90;
      G.line(ctx, [[x, 387 + row * 68], [x + 24, 387 + row * 68]], C.steel, 2.4);
    }
  }
  ctx.restore(); reservoirPath(); ctx.strokeStyle = C.ink; ctx.lineWidth = 4; ctx.stroke();
  G.box(ctx, 109, 649, 520, 18, C.steel, 5, C.ink, 3.5);

  // Side section of the dam is a single solid polygon, not an extruded object.
  ctx.beginPath(); ctx.moveTo(470, 276); ctx.lineTo(533, 276);
  ctx.lineTo(624, 649); ctx.lineTo(470, 649); ctx.closePath();
  ctx.fillStyle = C.white; ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 4; ctx.stroke();
  G.line(ctx, [[490, 298], [490, 620], [599, 620]], C.steel, 2.5);
  for (let i = 0; i < 5; i++) G.line(ctx, [[494, 331 + i * 57], [530 + i * 12, 331 + i * 57]], C.ice, 2.5);
  G.box(ctx, 451, 260, 104, 18, C.pale, 4, C.ink, 3.5);
  G.line(ctx, [[446, 241], [563, 241]], C.ink, 3);
  for (let i = 0; i < 5; i++) G.line(ctx, [[451 + i * 26, 242], [451 + i * 26, 259]], C.ink, 2.5);

  // Gate control cabin and actuator, anchored to the crest.
  G.box(ctx, 454, 181, 98, 78, C.white, 7, C.ink, 3.5);
  G.box(ctx, 447, 171, 112, 13, C.deep, 4, C.ink, 3);
  G.box(ctx, 467, 197, 72, 32, C.ice, 4, C.ink, 2.5);
  G.line(ctx, [[503, 199], [503, 227]], C.white, 3);
  G.circle(ctx, 479, 244, 3, C.blue, C.ink, 1.5);
  G.line(ctx, [[493, 244], [534, 244]], C.steel, 2.5);
  G.line(ctx, [[502, 279], [502, 427]], C.ink, 7);
  G.line(ctx, [[502, 279], [502, 427]], C.steel, 3);
  G.circle(ctx, 502, 320, 16, C.white, C.ink, 3);
  G.line(ctx, [[492, 320], [512, 320]], C.blue, 3);
  G.line(ctx, [[502, 310], [502, 330]], C.blue, 3);

  // Tailrace is a bounded open-water diagram below the power equipment.
  function tailracePath() {
    ctx.beginPath();
    for (let i = 0; i <= 85; i++) {
      const u = i / 85;
      const wave = 4.5 * Math.pow(Math.sin(Math.PI * u), 2) * Math.sin(G.TAU * (3 * u - phase * 5 + 0.2));
      const x = 1018 + 453 * u, y = 718 + wave;
      if (!i) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.lineTo(1471, 781); ctx.quadraticCurveTo(1471, 794, 1458, 794);
    ctx.lineTo(1031, 794); ctx.quadraticCurveTo(1018, 794, 1018, 781); ctx.closePath();
  }
  tailracePath(); ctx.fillStyle = C.pale; ctx.fill();
  ctx.save(); tailracePath(); ctx.clip();
  ctx.fillStyle = C.ice; ctx.fillRect(1013, 757, 465, 43);
  for (let row = 0; row < 2; row++) for (let i = -1; i < 7; i++) {
    const x = 987 + (i + G.fract(phase * 5)) * 80;
    G.line(ctx, [[x, 738 + row * 33], [x + 24, 738 + row * 33]], C.steel, 2.1);
  }
  ctx.restore(); tailracePath(); ctx.strokeStyle = C.ink; ctx.lineWidth = 4; ctx.stroke();

  tube(ctx, routes.penstock, phase, C.blue, 33, 0.15);
  tube(ctx, routes.discharge, phase, C.blue, 30, 0.53, 20, true);
  G.cable(ctx, routes.power, phase, 0.35);

  // The intake rack deliberately masks the entering end of the penstock.
  G.box(ctx, 412, 392, 34, 70, C.pale, 5, C.ink, 3);
  for (let i = 0; i < 4; i++) G.line(ctx, [[419 + i * 7, 399], [419 + i * 7, 455]], C.deep, 2.5);
  for (const y of [412, 442]) G.line(ctx, [[413, y], [445, y]], C.ink, 2);

  // Flanges are attached to the pipe, safely clear of all moving blades.
  const flangeX = 714;
  G.box(ctx, flangeX, 551, 13, 48, C.pale, 4, C.ink, 3);
  for (const y of [557, 593]) G.circle(ctx, flangeX + 6.5, y, 1.8, C.ink, null, 0);

  // A fixed shaft joins turbine and generator. Rotating parts stay in housings.
  G.box(ctx, 922, 568, 136, 14, C.steel, 4, C.ink, 3);
  G.box(ctx, 978, 560, 17, 30, C.pale, 4, C.ink, 3);
  G.box(ctx, 792, 636, 18, 57, C.steel, 4, C.ink, 3);
  G.box(ctx, 890, 636, 18, 57, C.steel, 4, C.ink, 3);
  G.box(ctx, 772, 690, 52, 13, C.pale, 4, C.ink, 3);
  G.box(ctx, 878, 690, 52, 13, C.pale, 4, C.ink, 3);
  rotor(ctx, 850, 575, 88, phase, 10, C.blue);
  generator(ctx, 1040, 496, 178, 161, phase);
  switchgear(ctx, 1342, 456, 132, 205, phase);

  // The flat, uncapped outlet opens directly into the visible tailrace.
  ctx.restore();
}

// Concept 04: Geothermal Circuit - Earth Heat Power System
// Pure Canvas 2D. Duration: 25 s. Seamless. No external assets or dependencies.
// Encoder export target: 3840 x 2160, 60 fps, 100000000 bits/s (100 Mbps).
// Configure bitrate in the video encoder; drawing code does not set bitrate.

const GE_GEO = (() => {
  'use strict';
  const TAU = Math.PI * 2;
  const C = Object.freeze({
    ink: '#192944', blue: '#3568D4', deep: '#244A91', pale: '#E8EFFF',
    ice: '#C6D8FA', white: '#FFFCF5', purple: '#7662C7',
    amber: '#F4B449', coral: '#EE8876', steel: '#A8BCDF'
  });
  const clamp = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
  const fract = v => v - Math.floor(v);

  function rounded(ctx, x, y, w, h, r = 8) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }
  function box(ctx, x, y, w, h, fill, r = 8, stroke = C.ink, line = 3.5) {
    rounded(ctx, x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && line > 0) { ctx.lineWidth = line; ctx.strokeStyle = stroke; ctx.stroke(); }
  }
  function line(ctx, points, color = C.ink, width = 3) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke = C.ink, width = 3) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && width > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function bolt(ctx, x, y, scale = 1, color = C.amber) {
    ctx.save(); ctx.translate(x, y); ctx.scale(scale, scale);
    ctx.beginPath();
    ctx.moveTo(3, -18); ctx.lineTo(-12, 3); ctx.lineTo(-1, 3);
    ctx.lineTo(-5, 19); ctx.lineTo(13, -5); ctx.lineTo(2, -5);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill();
    ctx.restore();
  }
  function label(ctx, text, x, y, size = 12, color = C.ink) {
    ctx.fillStyle = color;
    ctx.font = '600 ' + size + 'px "Nimbus Sans", Arial, sans-serif';
    ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
    ctx.fillText(text, x, y);
  }
  function mix(a, b, u) {
    u = clamp(u);
    const ai = parseInt(a.slice(1), 16), bi = parseInt(b.slice(1), 16);
    const r = Math.round((ai >> 16) * (1 - u) + (bi >> 16) * u);
    const g = Math.round(((ai >> 8) & 255) * (1 - u) + ((bi >> 8) & 255) * u);
    const bl = Math.round((ai & 255) * (1 - u) + (bi & 255) * u);
    return 'rgb(' + r + ',' + g + ',' + bl + ')';
  }

  // Precomputed arc-length tables keep packets moving smoothly around bends.
  function route(points, radius = 15) {
    const commands = [], samples = [];
    function sample(x, y) {
      const last = samples[samples.length - 1];
      const distance = last ? last.d + Math.hypot(x - last.x, y - last.y) : 0;
