    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = stroke; ctx.lineWidth = sw; ctx.stroke();
  }
  function circle(x, y, r, fill, stroke, sw = 3) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = sw; ctx.stroke(); }
  }
  function ellipse(x, y, rx, ry, fill, stroke, sw = 3) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = sw; ctx.stroke(); }
  }
  function label(text, x, y, size, color = C.ink, align = 'left', weight = 600) {
    ctx.font = weight + ' ' + size + 'px "DejaVu Sans", Arial, Helvetica, sans-serif';
    ctx.textAlign = align; ctx.textBaseline = 'middle'; ctx.fillStyle = color;
    ctx.fillText(text, x, y);
  }
  function bolt(x, y, r = 3.3) {
    circle(x, y, r, C.paper, C.steel, 1.1);
    line([[x - r * 0.45, y], [x + r * 0.45, y]], C.steel, 1);
  }
  function lightning(x, y, s, color = C.amber) {
    poly([[x + s * 0.12, y - s * 0.5], [x - s * 0.32, y + s * 0.06],
      [x - s * 0.02, y + s * 0.06], [x - s * 0.13, y + s * 0.5],
      [x + s * 0.34, y - s * 0.12], [x + s * 0.04, y - s * 0.12]], color, null);
  }
  function box(x, y, w, h, d, front = C.paper, side = C.silver) {
    poly([[x + w, y], [x + w + d, y - d],
      [x + w + d, y + h - d], [x + w, y + h]], side);
    poly([[x, y], [x + d, y - d], [x + w + d, y - d], [x + w, y]], C.white);
    rect(x, y, w, h, 5, front, C.ink);
  }
  // Rounded, arc-length sampled cable. Packets follow the physical route.
  function route(knots, radius = 16) {
    const points = [knots[0]];
    function add(p) {
      const a = points[points.length - 1];
      if (Math.hypot(p[0] - a[0], p[1] - a[1]) > 0.0001) points.push(p);
    }
    for (let i = 1; i < knots.length - 1; i++) {
      const a = knots[i - 1], b = knots[i], c = knots[i + 1];
      const da = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const db = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const r = Math.min(radius, da * 0.45, db * 0.45);
      const p = [b[0] + (a[0] - b[0]) * r / da, b[1] + (a[1] - b[1]) * r / da];
      const q = [b[0] + (c[0] - b[0]) * r / db, b[1] + (c[1] - b[1]) * r / db];
      add(p);
      for (let k = 1; k <= 12; k++) {
        const u = k / 12, v = 1 - u;
        add([v * v * p[0] + 2 * v * u * b[0] + u * u * q[0],
          v * v * p[1] + 2 * v * u * b[1] + u * u * q[1]]);
      }
    }
    add(knots[knots.length - 1]);
    const lengths = [0];
    for (let i = 1; i < points.length; i++) {
      lengths.push(lengths[i - 1] + Math.hypot(points[i][0] - points[i - 1][0], points[i][1] - points[i - 1][1]));
    }
    return { points, lengths, length: lengths[lengths.length - 1] };
  }
  function routePoint(r, fraction) {
    const d = clamp(fraction, 0, 1) * r.length;
    let i = 1;
    while (i < r.lengths.length - 1 && r.lengths[i] < d) i++;
    const a = r.points[i - 1], b = r.points[i];
    const f = (d - r.lengths[i - 1]) / (r.lengths[i] - r.lengths[i - 1]);
    return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f];
  }
  function cable(r, laps = 3, count = 4, offset = 0, thickness = 11) {
    line(r.points, C.ink, thickness + 4);
    line(r.points, C.paleBlue, thickness);
    for (let i = 0; i < count; i++) {
      const f = ((cycle * laps + i / count + offset) % 1 + 1) % 1;
      const p = routePoint(r, f);
      const a = routePoint(r, Math.max(0, f - 0.012));
      const b = routePoint(r, Math.min(1, f + 0.012));
      const edge = Math.min(1, f / 0.07, (1 - f) / 0.07);
      const tint = mix(C.paleBlue, C.amber, edge * edge * (3 - 2 * edge));
      ctx.save(); ctx.translate(p[0], p[1]);
      ctx.rotate(Math.atan2(b[1] - a[1], b[0] - a[0]));
      rect(-7, -thickness * 0.29, 14, thickness * 0.58, 3, tint, null);
      ctx.restore();
    }
  }

  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.setLineDash([]);
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  ctx.translate((width - 1600 * scale) / 2, (height - 900 * scale) / 2);
  ctx.scale(scale, scale);

  // One fixed scene: photovoltaic arrays, inverter, storage, and AC load.
  poly([[95, 654], [1395, 654], [1500, 737], [200, 737]], C.paper);
  poly([[200, 737], [1500, 737], [1500, 760], [200, 760]], C.silver);
  poly([[95, 654], [200, 737], [200, 760], [95, 677]], C.steel);
  line([[214, 749], [1484, 749]], C.white, 2);
  for (const x of [270, 715, 1040, 1425]) bolt(x, 750, 3.4);

  const solarLine = route([[652, 600], [705, 600], [705, 689], [859, 689], [859, 648]], 19);
  const storageLine = route([[977, 598], [1021, 598], [1021, 689], [1178, 689], [1178, 645]], 18);
  const loadLine = route([[1254, 645], [1254, 713], [1387, 713], [1387, 662]], 18);
  cable(solarLine, 3, 4, 0);
  cable(storageLine, 3, 4, 0.2);
  cable(loadLine, 3, 4, 0.4);

  // Solid sun, restrained rays, and a completely opaque face.
  ctx.save(); ctx.translate(406, 210); ctx.rotate(phase / 12);
  for (let i = 0; i < 12; i++) {
    const a = i * TAU / 12;
    line([[Math.cos(a) * 66, Math.sin(a) * 66],
      [Math.cos(a) * 78, Math.sin(a) * 78]], C.ink, 5);
  }
  ctx.restore();
  circle(406, 210, 48, C.amber, C.ink, 3.5);
  ctx.save(); ctx.beginPath(); ctx.arc(406, 210, 45, 0, TAU); ctx.clip();
  ctx.fillStyle = C.amberLight; ctx.beginPath();
  ctx.ellipse(392, 187, 36, 25, -0.38, 0, TAU); ctx.fill(); ctx.restore();
  ctx.beginPath(); ctx.arc(406, 210, 35, 3.55, 4.65);
  ctx.strokeStyle = C.white; ctx.lineWidth = 3; ctx.stroke();

  function panelSupport(x, y) {
    line([[x + 22, y + 113], [x + 22, 660]], C.ink, 13);
    line([[x + 22, y + 113], [x + 22, 660]], C.silver, 7);
    line([[x + 346, y + 113], [x + 346, 660]], C.ink, 13);
    line([[x + 346, y + 113], [x + 346, 660]], C.silver, 7);
    line([[x + 22, y + 147], [x + 346, 650]], C.steel, 5);
    rect(x + 4, 656, 38, 10, 3, C.silver, C.ink, 2);
    rect(x + 329, 656, 38, 10, 3, C.silver, C.ink, 2);
  }
  // Draw supports first, then the immutable planar panel geometry.
  panelSupport(190, 342);
  panelSupport(235, 504);

  function solarPanel(x, y, offset) {
    ctx.save(); ctx.translate(x, y); ctx.transform(1, 0, -0.32, 0.72, 0, 0);
    rect(0, 5, 460, 186, 7, C.steel, C.ink, 3);
    rect(0, 0, 460, 186, 7, C.silver, C.ink, 3.5);
    rect(9, 9, 442, 168, 3, C.navy, C.ink, 2);
    const cols = 8, rows = 4, gap = 5;
    const cw = (426 - (cols - 1) * gap) / cols;
    const ch = (152 - (rows - 1) * gap) / rows;
    for (let row = 0; row < rows; row++) {
      for (let col = 0; col < cols; col++) {
        const xx = 17 + col * (cw + gap), yy = 17 + row * (ch + gap);
        const light = 0.5 + 0.5 * Math.sin(phase * 2 - col * 0.23 - row * 0.15 + offset);
        rect(xx, yy, cw, ch, 2, mix('#284B84', '#3C68AA', light), null);
        line([[xx + 5, yy + 4], [xx + cw - 5, yy + 4]], '#809BC5', 1.3);
        line([[xx + cw / 2, yy + 3], [xx + cw / 2, yy + ch - 3]], '#95B1D9', 1);
      }
    }
    // A narrow matte reflection moves periodically inside the panel only.
    ctx.save(); roundPath(10, 10, 440, 166, 2); ctx.clip();
    const sweep = 230 + 275 * Math.sin(phase - 0.65 + offset * 0.2);
    poly([[sweep - 32, 10], [sweep - 16, 10], [sweep + 61, 176], [sweep + 45, 176]], '#6489BC', null);
    ctx.restore();
    line([[230, 9], [230, 177]], C.silver, 4);
    for (const px of [5, 455]) for (const py of [5, 181]) bolt(px, py, 2.1);
    ctx.restore();
  }
  solarPanel(190, 342, 0);
  solarPanel(235, 504, 0.8);
  // A DC connector is attached to the front array's right frame.
  ctx.save(); ctx.translate(652, 600); ctx.rotate(0.42);
  rect(-5, -8, 15, 16, 3, C.ink, C.ink, 2);
  ctx.restore();

  // Inverter cabinet; all controls are inset and retain fixed dimensions.
  box(777, 430, 188, 225, 24, C.white, C.silver);
  rect(790, 444, 162, 27, 5, C.paper, C.silver, 1.5);
  label('INVERTER', 871, 458, 15, C.ink, 'center', 700);
  rect(795, 485, 136, 74, 7, C.navy, C.ink, 2);
  label('DC / AC', 808, 501, 11, C.paleBlue, 'left', 600);
  line([[807, 541], [918, 541]], '#607B9F', 1);
  ctx.save(); roundPath(803, 514, 120, 35, 3); ctx.clip();
  ctx.beginPath();
  for (let i = 0; i <= 100; i++) {
    const xx = 808 + i * 1.08;
    const yy = 531 - Math.sin(i / 100 * TAU * 1.4 - phase * 5) * 10;
    if (i === 0) ctx.moveTo(xx, yy); else ctx.lineTo(xx, yy);
  }
  ctx.strokeStyle = C.amberLight; ctx.lineWidth = 2.8; ctx.stroke(); ctx.restore();
  for (let i = 0; i < 4; i++) line([[947, 493 + i * 14], [947, 501 + i * 14]], C.steel, 2.3);
  rect(795, 575, 136, 13, 4, C.paper, C.silver, 1.4);
  const power = 0.66 + 0.14 * Math.sin(phase);
  rect(799, 579, 128 * power, 5, 2, C.blue, null);
  circle(815, 616, 14, C.paper, C.ink, 2);
  circle(815, 616, 5, C.blue, null);
  circle(853, 616, 14, C.paper, C.ink, 2);
  lightning(853, 616, 16, C.ink);
  for (let i = 0; i < 4; i++) line([[887, 606 + i * 7], [930, 606 + i * 7]], C.steel, 2);
  for (const p of [[786, 439], [956, 439], [786, 646], [956, 646]]) bolt(p[0], p[1], 2.7);
  rect(845, 649, 28, 12, 3, C.navy, C.ink, 2);
  rect(969, 587, 17, 24, 3, C.navy, C.ink, 2);
  rect(788, 655, 28, 13, 3, C.navy2, C.ink, 2);
  rect(930, 655, 27, 13, 3, C.navy2, C.ink, 2);

  // Energy storage: six discrete, aligned modules with opaque indicators.
  box(1090, 307, 190, 351, 25, C.white, C.silver);
  rect(1105, 322, 160, 33, 5, C.paper, C.silver, 1.5);
  label('ENERGY STORAGE', 1185, 339, 13, C.ink, 'center', 700);
  const charge = 0.66 + 0.18 * Math.sin(phase);
  for (let row = 0; row < 6; row++) {
    const yy = 373 + row * 43;
    rect(1106, yy, 158, 33, 4, C.paper, C.steel, 1.7);
    for (let col = 0; col < 7; col++) {
      const q = clamp((charge - col / 7) * 7, 0, 1);
      rect(1120 + col * 17.7, yy + 9, 12.7, 15, 2,
        mix(C.silver, C.blue, q * q * (3 - 2 * q)), null);
    }
    line([[1112, yy + 12], [1112, yy + 21]], C.steel, 2);
    bolt(1257, yy + 16.5, 2.2);
  }
  rect(1110, 636, 150, 8, 3, C.navy, null);
  rect(1163, 650, 30, 13, 3, C.navy, C.ink, 2);
  rect(1240, 650, 29, 13, 3, C.navy, C.ink, 2);
  for (let i = 0; i < 8; i++) line([[1289, 380 + i * 24], [1298, 371 + i * 24]], C.steel, 2);
  for (const p of [[1099, 316], [1271, 316], [1099, 649], [1271, 649]]) bolt(p[0], p[1], 2.7);
  rect(1103, 658, 27, 13, 3, C.navy2, C.ink, 2);
  rect(1241, 658, 27, 13, 3, C.navy2, C.ink, 2);

  // The compact AC distribution pedestal provides a clear destination.
  box(1349, 526, 73, 142, 13, C.white, C.silver);
  rect(1358, 538, 55, 24, 4, C.navy, C.ink, 1.5);
  label('AC', 1385.5, 550, 13, C.white, 'center', 700);
  circle(1385.5, 587, 17, C.paper, C.ink, 2);
  line([[1380, 582], [1380, 588]], C.ink, 2.4);
  line([[1391, 582], [1391, 588]], C.ink, 2.4);
  line([[1386, 593], [1386, 596]], C.ink, 2.4);
  for (let i = 0; i < 3; i++) {
    const v = 0.5 + 0.5 * Math.sin(phase + i * 0.7);
    rect(1364 + i * 15, 618 - v * 9, 9, 18 + v * 9, 2, i === 2 ? C.amber : C.blue, null);
  }
  rect(1374, 660, 25, 13, 3, C.navy, C.ink, 2);
  rect(1358, 668, 55, 11, 3, C.navy2, C.ink, 2);
  ctx.restore();
}

/**
 * Concept 03 - Hydropower / Turbine Cutaway System
 * 25 seconds | one continuous scene | 16:9 UHD | seamless periodic animation.
 * Canvas 2D only; no assets, external code, glow, blur, or frame accumulation.
 * Render time is in SECONDS. Recommended video frame rate: 60 fps.
 * Video export: set MANUAL 100 Mbps (100,000,000 bits/second) in Prysm.
 * The drawing function itself does not encode video or control its bitrate.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1600, height / 900, minSide / 900);
  const tau = Math.PI * 2;
  const phase = (currentScene + sceneProgress) / sceneCount;
  const angle = tau * phase;
  const flowPhase = 5 * loopT / duration;
  const C = {
    ink: '#17253E', navy: '#243B61', blue: '#365E98', blueLight: '#85A5CF',
    white: '#F5F7FC', silver: '#E3E9F3', steel: '#B6C2D4', side: '#8F9EB6',
    darkSteel: '#657894', amber: '#E7AA4C', copper: '#B97436', muted: '#CAD4E4'
  };

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.translate((width - 1600 * scale) * 0.5, (height - 900 * scale) * 0.5);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  function polygon(points, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function roundedPath(x, y, w, h, radius) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function roundRect(x, y, w, h, radius, fill, stroke, lineWidth) {
    roundedPath(x, y, w, h, radius);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function line(points, color, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function circle(x, y, radius, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, tau);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.3; ctx.stroke(); }
  }

  function label(text, x, y, maxWidth, size, color, align) {
    ctx.save();
    let fontSize = size;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    const measured = ctx.measureText(text).width;
    if (measured > maxWidth) fontSize *= maxWidth / measured;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function bolt(x, y, r) {
    circle(x, y, r || 2.1, C.darkSteel);
    line([[x - 0.8, y], [x + 0.8, y]], C.silver, 0.8);
  }

  function lightning(x, y, size, color) {
    polygon([
      [x + size * 0.08, y - size * 0.5], [x - size * 0.34, y + size * 0.05],
      [x - size * 0.03, y + size * 0.05], [x - size * 0.13, y + size * 0.5],
      [x + size * 0.34, y - size * 0.1], [x + size * 0.04, y - size * 0.1]
    ], color);
  }

  // Tangent-continuous cable corners, sampled once per cable per frame.
  function makeRoute(points, radius) {
    const samples = [points[0]];
    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1], b = points[i], c = points[i + 1];
      const da = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const db = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const r = Math.min(radius, da * 0.45, db * 0.45);
      const enter = [b[0] + (a[0] - b[0]) * r / da, b[1] + (a[1] - b[1]) * r / da];
      const leave = [b[0] + (c[0] - b[0]) * r / db, b[1] + (c[1] - b[1]) * r / db];
      samples.push(enter);
      for (let k = 1; k <= 10; k++) {
        const u = k / 10, v = 1 - u;
        samples.push([v * v * enter[0] + 2 * v * u * b[0] + u * u * leave[0],
                      v * v * enter[1] + 2 * v * u * b[1] + u * u * leave[1]]);
      }
    }
    samples.push(points[points.length - 1]);
    const lengths = [0];
    for (let i = 1; i < samples.length; i++) {
      lengths.push(lengths[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, lengths: lengths, total: lengths[lengths.length - 1] };
  }

  function routePoint(route, distance) {
    const d = Math.max(0, Math.min(route.total, distance));
    for (let i = 1; i < route.samples.length; i++) {
      if (d <= route.lengths[i]) {
        const a = route.samples[i - 1], b = route.samples[i];
        const u = (d - route.lengths[i - 1]) / Math.max(0.0001, route.lengths[i] - route.lengths[i - 1]);
        return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u];
      }
    }
    return route.samples[route.samples.length - 1];
  }

  function cable(points, cableWidth, cycle, count) {
    const route = makeRoute(points, 11);
    line(route.samples, C.ink, cableWidth);
    line(route.samples, C.darkSteel, Math.max(1, cableWidth - 3));
    for (let i = 0; i < count; i++) {
      const u = ((cycle + i / count) % 1 + 1) % 1;
      const envelope = Math.pow(Math.sin(Math.PI * u), 2);
      const half = Math.min(13 * envelope, u * route.total, (1 - u) * route.total);
      if (half < 0.02) continue;
      const trail = [];
      for (let k = 0; k <= 10; k++) trail.push(routePoint(route, u * route.total - half + 2 * half * k / 10));
      const edge = Math.min(1, u / 0.1, (1 - u) / 0.1);
      line(trail, C.amber, cableWidth * 0.42 * edge * edge * (3 - 2 * edge));
    }
  }

  function enclosure(x, y, w, h, depth) {
    const dx = depth, dy = -depth * 0.58;
    polygon([[x, y], [x + dx, y + dy], [x + w + dx, y + dy], [x + w, y]], C.white, C.ink);
    polygon([[x + w, y], [x + w + dx, y + dy], [x + w + dx, y + h + dy], [x + w, y + h]], C.side, C.ink);
    const metal = ctx.createLinearGradient(x, y, x + w, y);
    metal.addColorStop(0, C.white);
    metal.addColorStop(0.55, C.silver);
    metal.addColorStop(1, '#D2DBE9');
    roundRect(x, y, w, h, 5, metal, C.ink, 1.7);
    line([[x + 6, y + 10], [x + 6, y + h - 10]], C.white, 2);
    line([[x + w + dx * 0.48, y + dy * 0.48 + 12], [x + w + dx * 0.48, y + h + dy * 0.48 - 12]], C.darkSteel, 1);
  }

  function ellipse(x, y, rx, ry, fill, stroke, lineWidth) {
    ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, tau);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function curveRoute(start, segments) {
    const samples = [start];
    let a = start;
    for (let i = 0; i < segments.length; i++) {
      const s = segments[i];
      for (let k = 1; k <= 28; k++) {
        const u = k / 28, v = 1 - u;
        samples.push([v*v*v*a[0] + 3*v*v*u*s[0] + 3*v*u*u*s[2] + u*u*u*s[4],
                      v*v*v*a[1] + 3*v*v*u*s[1] + 3*v*u*u*s[3] + u*u*u*s[5]]);
      }
      a = [s[4], s[5]];
    }
    const lengths = [0];
    for (let i = 1; i < samples.length; i++) {
      lengths.push(lengths[i-1] + Math.hypot(samples[i][0]-samples[i-1][0], samples[i][1]-samples[i-1][1]));
    }
    return { samples: samples, lengths: lengths, total: lengths[lengths.length-1] };
  }

  // Constant arc-length advection. A smooth zero-length envelope prevents endpoint pops.
  function tracers(route, cycle, count, color, strokeWidth, trailLength) {
    for (let i = 0; i < count; i++) {
      const u = ((cycle + i / count) % 1 + 1) % 1;
      const envelope = Math.pow(Math.sin(Math.PI * u), 2);
      const half = Math.min((trailLength || 16) * envelope, u * route.total, (1-u) * route.total);
      if (half < 0.00001) continue;
      const points = [];
      for (let j = 0; j <= 12; j++) points.push(routePoint(route, u * route.total - half + 2 * half * j / 12));
      const edge = Math.min(1, u / 0.1, (1-u) / 0.1);
      line(points, color, strokeWidth * edge * edge * (3 - 2*edge));
    }
  }

  function pipe(points, diameter, fluidColor, cycle, count, tracerColor, bend) {
    const route = makeRoute(points, bend || 23);
    line(route.samples, C.ink, diameter + 2.8);
    line(route.samples, '#B9C6D9', diameter);
    line(route.samples, C.navy, diameter - 8);
    line(route.samples, fluidColor, diameter - 12);
    tracers(route, cycle, count, tracerColor || C.blueLight, Math.max(2, (diameter-12)*0.22), 20);
    return route;
  }

  function flange(x, y, diameter, orientation) {
    ctx.save(); ctx.translate(x, y); ctx.rotate(orientation || 0);
    // Only the metal rim is overlaid; the center cutaway remains open.
    line([[-5, -diameter/2-3], [5, -diameter/2-3]], C.ink, 3);
    line([[-5, diameter/2+3], [5, diameter/2+3]], C.ink, 3);
    bolt(0, -diameter/2-3, 2.1); bolt(0, diameter/2+3, 2.1);
    ctx.restore();
