  function runner(radius, spin, count, color) {
    ctx.save(); ctx.rotate(spin);
    for (let i = 0; i < count; i++) {
      ctx.save(); ctx.rotate(i * tau / count);
      ctx.beginPath();
      ctx.moveTo(radius*.22, -radius*.07);
      ctx.bezierCurveTo(radius*.48, -radius*.25, radius*.85, -radius*.24, radius*.97, -radius*.01);
      ctx.bezierCurveTo(radius*.98, radius*.12, radius*.71, radius*.2, radius*.4, radius*.11);
      ctx.lineTo(radius*.2, radius*.04); ctx.closePath();
