    circle(0, 0, radius*.30, C.steel, C.ink, 1.3);
    circle(0, 0, radius*.11, C.white, C.darkSteel, 0.9);
    ctx.restore();
  }

  function turbineCasing(x, y, radius, spin, warm) {
    const compression = 0.72, depth = 24;
    ellipse(x+depth, y, radius*compression, radius, C.side, C.ink, 1.6);
    const shell = ctx.createLinearGradient(x, y-radius, x, y+radius);
    shell.addColorStop(0, C.white); shell.addColorStop(1, C.steel);
    polygon([[x, y-radius], [x+depth, y-radius], [x+depth, y+radius], [x, y+radius]], shell);
    ctx.save(); ctx.translate(x, y); ctx.scale(compression, 1);
    circle(0, 0, radius, shell, C.ink, 1.8);
    circle(0, 0, radius-9, C.navy, C.darkSteel, 1.2);
    circle(0, 0, radius-16, warm ? '#705763' : '#315C94');
    for (let i = 0; i < 10; i++) {
      ctx.save(); ctx.rotate(i*tau/10);
      ctx.beginPath();
      ctx.moveTo(radius-14, -3);
      ctx.quadraticCurveTo(radius-22, -10, radius-27, -4);
      ctx.strokeStyle = C.steel; ctx.lineWidth = 2; ctx.stroke();
      ctx.restore();
    }
    const waterR = radius-20;
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      const a = angle*4 + i*tau/4;
      ctx.arc(0, 0, waterR, a, a+0.16);
      ctx.strokeStyle = warm ? '#D8AF88' : '#8AAFD9'; ctx.lineWidth = 2.8; ctx.stroke();
    }
    circle(0, 0, radius*.55, C.navy, C.ink, 1.1);
    runner(radius*.48, spin, 9, C.silver);
    for (let i = 0; i < 8; i++) {
      const a = i*tau/8;
      bolt(Math.cos(a)*(radius-4.7), Math.sin(a)*(radius-4.7), 2.1);
    }
    ctx.restore();
  }

  function generator(x, y, depth, radius, spin, floorY, tag) {
    const rx = radius*.49;
    for (let i = 0; i < 2; i++) {
      const xx = x+depth*(i === 0 ? .25 : .83);
      roundRect(xx-8, y+radius-8, 16, floorY-y-radius+8, 2, C.side, C.ink, 1.2);
      roundRect(xx-22, floorY-5, 44, 8, 2, C.steel, C.ink, 1.2);
    }
    ellipse(x+depth, y, rx, radius, C.side, C.ink, 1.6);
    const steel = ctx.createLinearGradient(x, y-radius, x, y+radius);
    steel.addColorStop(0, C.white); steel.addColorStop(.55, '#D3DDEB'); steel.addColorStop(1, '#9CACC4');
    ctx.fillStyle = steel; ctx.fillRect(x, y-radius, depth, radius*2);
    line([[x, y-radius], [x+depth, y-radius]], C.ink, 1.5);
    line([[x, y+radius], [x+depth, y+radius]], C.ink, 1.5);
    for (let i = 0; i < 5; i++) line([[x+rx+9, y-15+i*10], [x+depth-12, y-15+i*10]], C.darkSteel, 1.5);
    roundRect(x+rx+7, y-radius+12, Math.max(42, depth-rx-17), 19, 2, C.silver, C.side, 1);
    label(tag, x+(depth+rx)/2, y-radius+22, Math.max(36, depth-rx-23), 10, C.ink, 'center');
    ellipse(x, y, rx, radius, C.white, C.ink, 1.7);
    ctx.save(); ctx.translate(x, y); ctx.scale(.49, 1);
    circle(0, 0, radius-7, C.navy, C.darkSteel, 1.4);
    for (let i = 0; i < 10; i++) {
      ctx.save(); ctx.rotate(i*tau/10);
      roundRect(radius*.60, -radius*.105, radius*.20, radius*.21, 2.3, C.copper, '#E4B477', 1);
      ctx.restore();
    }
    circle(0, 0, radius*.48, C.darkSteel, C.steel, 1.2);
    runner(radius*.41, spin, 6, C.silver);
    ctx.restore();
  }

  ctx.translate(0, -42);
  const spin = angle * 8;
  // Reservoir: a contained, opaque cutaway; the chroma field is never tinted.
  polygon([[140, 650], [650, 650], [690, 625], [180, 625]], C.steel, C.ink, 1.5);
  polygon([[140, 650], [650, 650], [650, 674], [140, 674]], C.side, C.ink, 1.5);
  polygon([[650, 650], [690, 625], [690, 649], [650, 674]], '#8395B1', C.ink, 1.5);
  polygon([[140, 283], [190, 251], [190, 625], [140, 650]], '#B7C3D6', C.ink, 1.5);
  const water = ctx.createLinearGradient(0, 307, 0, 635);
  water.addColorStop(0, '#4A79B6'); water.addColorStop(1, '#244475');
  polygon([[153, 307], [208, 272], [490, 272], [470, 307]], '#7099C8', C.ink, 1.2);
  ctx.fillStyle = water; ctx.fillRect(153, 307, 337, 330);
  ctx.save();
  ctx.beginPath(); ctx.rect(153, 307, 337, 330); ctx.clip();
  for (let j = 0; j < 4; j++) {
    const points = [];
    for (let x = 153; x <= 491; x += 4) points.push([x, 324+j*9 + 1.6*Math.sin(tau*(x-153)/108 - angle*2 + j*.6)]);
    line(points, j % 2 === 0 ? '#91B1D7' : '#6289BA', 1.15);
  }
  for (let j = 0; j < 3; j++) {
    const y = 393 + j*67;
    const route = curveRoute([179, y], [[290, y, 375, 434+j*9, 468, 434+j*9]]);
    line(route.samples, '#426DA5', 1.5);
    tracers(route, flowPhase*.6 + j*.17, 3, '#85A8D2', 2, 19);
  }
  ctx.restore();
  polygon([[140, 283], [153, 291], [153, 637], [140, 650]], C.silver, C.ink, 1.4);
  line([[153, 637], [484, 637]], C.steel, 7);
  line([[153, 308], [153, 628]], '#E4EAF4', 1.2);

  // Gravity dam with an explicit technical opening for its embedded penstock.
  const concrete = ctx.createLinearGradient(470, 0, 650, 0);
  concrete.addColorStop(0, '#E9EDF5'); concrete.addColorStop(1, '#B7C4D8');
  polygon([[540, 245], [580, 219], [690, 624], [650, 650]], '#93A4BF', C.ink, 1.7);
  polygon([[470, 245], [540, 245], [650, 650], [470, 650]], concrete, C.ink, 1.7);
  for (let i = 1; i < 5; i++) {
    const y = 245+i*81, right = 540+110*(y-245)/405;
    line([[477, y], [right-3, y]], '#AEBED3', 1.0);
  }
  polygon([[458, 225], [558, 225], [598, 199], [498, 199]], C.white, C.ink, 1.4);
  polygon([[458, 225], [558, 225], [558, 245], [458, 245]], C.steel, C.ink, 1.4);
  for (let i = 0; i < 4; i++) line([[469+i*26, 224], [469+i*26, 202]], C.darkSteel, 2.2);
  line([[469, 202], [547, 202]], C.darkSteel, 2.2);

  // Plant slab and pipe saddle are static structural geometry.
  polygon([[685, 650], [1420, 650], [1460, 676], [725, 676]], '#DDE5F1', C.ink, 1.5);
  polygon([[725, 676], [1460, 676], [1460, 695], [725, 695]], '#9CACC4', C.ink, 1.5);
  polygon([[685, 650], [725, 676], [725, 695], [685, 669]], C.steel, C.ink, 1.5);
  roundRect(682, 480, 13, 170, 2, C.side, C.ink, 1.3);
  roundRect(709, 493, 13, 157, 2, C.steel, C.ink, 1.3);
  line([[690, 626], [713, 518]], C.darkSteel, 2.2);
  roundRect(671, 646, 64, 8, 2, C.steel, C.ink, 1.3);
  pipe([[470, 430], [615, 430], [745, 495], [830, 495]], 56, '#315C94', flowPhase, 6, '#8CB0D9', 30);
  flange(552, 430, 56, 0); flange(670, 457.5, 56, Math.atan2(65,130));
  for (let i = 0; i < 5; i++) line([[453+i*5, 412], [453+i*5, 448]], '#BACCE1', 1.7);

  // A dedicated slab aperture makes the tailwater outlet intentional and legible.
  roundRect(805, 666, 50, 29, 2, C.ink);
  pipe([[830, 641], [830, 751], [982, 751]], 42, '#315C94', flowPhase+.23, 4, '#8CB0D9', 28);
  flange(830, 704, 42, Math.PI/2);

  // Mechanical shaft, bearing, and generator share one horizontal axis.
  roundRect(873, 562, 182, 16, 3, C.side, C.ink, 1.4);
  line([[875, 566], [1051, 566]], C.silver, 2.3);
  roundRect(947, 584, 18, 66, 2, C.side, C.ink, 1.2);
  roundRect(931, 646, 50, 8, 2, C.steel, C.ink, 1.2);
  ellipse(956, 570, 14, 20, C.steel, C.ink, 1.4);
  ellipse(956, 570, 7, 12, C.side, C.darkSteel, 1.0);
  cable([[1209, 570], [1256, 570], [1256, 601], [1320, 601]], 9, flowPhase+.48, 3);
  generator(1050, 570, 128, 63, spin, 650, 'GENERATOR');
  turbineCasing(830, 570, 80, spin, false);
  flange(830, 486, 56, Math.PI/2);

  enclosure(1320, 447, 100, 203, 23);
  label('GRID', 1370, 466, 76, 12, C.ink, 'center');
  roundRect(1334, 487, 72, 50, 4, C.navy, C.ink, 1.2);
  for (let i = 0; i < 5; i++) {
    const h = 10+17*(.5+.5*Math.sin(angle*3-i*.5));
    roundRect(1343+i*11, 529-h, 6, h, 1.4, C.amber);
  }
  for (let i = 0; i < 4; i++) roundRect(1339, 558+i*7, 61, 2.4, 1.2, C.side);
  circle(1370, 617, 14, C.navy); lightning(1370, 617, 18, C.amber);
  circle(1320, 601, 6.5, C.ink, C.steel); circle(1320, 601, 2.7, C.amber);
  circle(1209, 570, 6.1, C.ink, C.steel); circle(1209, 570, 2.5, C.amber);
  bolt(1330, 640); bolt(1410, 640);

  // Contained downstream basin, with all moving ripples clipped to the water.
  polygon([[970, 724], [1010, 700], [1420, 700], [1380, 724]], C.silver, C.ink, 1.5);
  polygon([[1380, 724], [1420, 700], [1420, 762], [1380, 786]], C.side, C.ink, 1.5);
  roundRect(970, 724, 410, 62, 3, C.silver, C.ink, 1.5);
  polygon([[982, 735], [1014, 713], [1400, 713], [1368, 735]], '#7399C8', C.ink, 1.0);
  ctx.fillStyle = '#365E98'; ctx.fillRect(982, 735, 386, 37);
  ctx.save(); ctx.beginPath(); ctx.rect(982, 735, 386, 37); ctx.clip();
  for (let j = 0; j < 3; j++) {
    const route = makeRoute([[982, 742+j*11], [1368, 742+j*11]], 1);
    tracers(route, flowPhase*.6+j*.18, 4, '#91B1D7', 1.8, 21);
  }
  ctx.restore();
  line([[981, 773], [1369, 773]], '#AEBED4', 3);
  ellipse(982, 751, 5, 15, '#365E98', C.darkSteel, 1.5);

  ctx.restore();
}

/**
 * Concept 04 - Geothermal / Deep Earth Power Station
 * 25 seconds | one continuous scene | 16:9 UHD | seamless periodic animation.
 * Canvas 2D only; no assets, external code, glow, blur, or frame accumulation.
 * Render time is in SECONDS. Recommended video frame rate: 60 fps.
 * Video export: set MANUAL 100 Mbps (100,000,000 bits/second) in Prysm.
 * The drawing function itself does not encode video or control its bitrate.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1600, height / 900, minSide / 900);
  const tau = Math.PI * 2;
  const phase = (currentScene + sceneProgress) / sceneCount;
  const angle = tau * phase;
  const flowPhase = 5 * loopT / duration;
  const C = {
    ink: '#17253E', navy: '#243B61', blue: '#365E98', blueLight: '#85A5CF',
    white: '#F5F7FC', silver: '#E3E9F3', steel: '#B6C2D4', side: '#8F9EB6',
    darkSteel: '#657894', amber: '#E7AA4C', copper: '#B97436', muted: '#CAD4E4'
  };

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.translate((width - 1600 * scale) * 0.5, (height - 900 * scale) * 0.5);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  function polygon(points, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function roundedPath(x, y, w, h, radius) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function roundRect(x, y, w, h, radius, fill, stroke, lineWidth) {
    roundedPath(x, y, w, h, radius);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function line(points, color, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function circle(x, y, radius, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, tau);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.3; ctx.stroke(); }
  }

  function label(text, x, y, maxWidth, size, color, align) {
    ctx.save();
    let fontSize = size;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    const measured = ctx.measureText(text).width;
    if (measured > maxWidth) fontSize *= maxWidth / measured;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function bolt(x, y, r) {
    circle(x, y, r || 2.1, C.darkSteel);
    line([[x - 0.8, y], [x + 0.8, y]], C.silver, 0.8);
  }

  function lightning(x, y, size, color) {
    polygon([
      [x + size * 0.08, y - size * 0.5], [x - size * 0.34, y + size * 0.05],
      [x - size * 0.03, y + size * 0.05], [x - size * 0.13, y + size * 0.5],
      [x + size * 0.34, y - size * 0.1], [x + size * 0.04, y - size * 0.1]
    ], color);
  }

  // Tangent-continuous cable corners, sampled once per cable per frame.
  function makeRoute(points, radius) {
    const samples = [points[0]];
    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1], b = points[i], c = points[i + 1];
      const da = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const db = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const r = Math.min(radius, da * 0.45, db * 0.45);
      const enter = [b[0] + (a[0] - b[0]) * r / da, b[1] + (a[1] - b[1]) * r / da];
      const leave = [b[0] + (c[0] - b[0]) * r / db, b[1] + (c[1] - b[1]) * r / db];
      samples.push(enter);
      for (let k = 1; k <= 10; k++) {
        const u = k / 10, v = 1 - u;
        samples.push([v * v * enter[0] + 2 * v * u * b[0] + u * u * leave[0],
                      v * v * enter[1] + 2 * v * u * b[1] + u * u * leave[1]]);
      }
    }
    samples.push(points[points.length - 1]);
    const lengths = [0];
    for (let i = 1; i < samples.length; i++) {
      lengths.push(lengths[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, lengths: lengths, total: lengths[lengths.length - 1] };
  }

  function routePoint(route, distance) {
    const d = Math.max(0, Math.min(route.total, distance));
    for (let i = 1; i < route.samples.length; i++) {
      if (d <= route.lengths[i]) {
        const a = route.samples[i - 1], b = route.samples[i];
        const u = (d - route.lengths[i - 1]) / Math.max(0.0001, route.lengths[i] - route.lengths[i - 1]);
        return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u];
      }
    }
    return route.samples[route.samples.length - 1];
  }

  function cable(points, cableWidth, cycle, count) {
    const route = makeRoute(points, 11);
    line(route.samples, C.ink, cableWidth);
    line(route.samples, C.darkSteel, Math.max(1, cableWidth - 3));
    for (let i = 0; i < count; i++) {
      const u = ((cycle + i / count) % 1 + 1) % 1;
      const envelope = Math.pow(Math.sin(Math.PI * u), 2);
      const half = Math.min(13 * envelope, u * route.total, (1 - u) * route.total);
      if (half < 0.02) continue;
      const trail = [];
      for (let k = 0; k <= 10; k++) trail.push(routePoint(route, u * route.total - half + 2 * half * k / 10));
      const edge = Math.min(1, u / 0.1, (1 - u) / 0.1);
      line(trail, C.amber, cableWidth * 0.42 * edge * edge * (3 - 2 * edge));
    }
  }

  function enclosure(x, y, w, h, depth) {
    const dx = depth, dy = -depth * 0.58;
    polygon([[x, y], [x + dx, y + dy], [x + w + dx, y + dy], [x + w, y]], C.white, C.ink);
    polygon([[x + w, y], [x + w + dx, y + dy], [x + w + dx, y + h + dy], [x + w, y + h]], C.side, C.ink);
    const metal = ctx.createLinearGradient(x, y, x + w, y);
    metal.addColorStop(0, C.white);
    metal.addColorStop(0.55, C.silver);
    metal.addColorStop(1, '#D2DBE9');
    roundRect(x, y, w, h, 5, metal, C.ink, 1.7);
    line([[x + 6, y + 10], [x + 6, y + h - 10]], C.white, 2);
    line([[x + w + dx * 0.48, y + dy * 0.48 + 12], [x + w + dx * 0.48, y + h + dy * 0.48 - 12]], C.darkSteel, 1);
  }

  function ellipse(x, y, rx, ry, fill, stroke, lineWidth) {
