  function curveRoute(start, segments) {
    const samples = [start];
    let a = start;
    for (let i = 0; i < segments.length; i++) {
      const s = segments[i];
      for (let k = 1; k <= 28; k++) {
        const u = k / 28, v = 1 - u;
        samples.push([v*v*v*a[0] + 3*v*v*u*s[0] + 3*v*u*u*s[2] + u*u*u*s[4],
                      v*v*v*a[1] + 3*v*v*u*s[1] + 3*v*u*u*s[3] + u*u*u*s[5]]);
      }
      a = [s[4], s[5]];
    }
    const lengths = [0];
    for (let i = 1; i < samples.length; i++) {
      lengths.push(lengths[i-1] + Math.hypot(samples[i][0]-samples[i-1][0], samples[i][1]-samples[i-1][1]));
    }
