      const envelope = Math.pow(Math.sin(Math.PI * u), 2);
      const half = Math.min((trailLength || 16) * envelope, u * route.total, (1-u) * route.total);
      if (half < 0.00001) continue;
      const points = [];
      for (let j = 0; j <= 12; j++) points.push(routePoint(route, u * route.total - half + 2 * half * j / 12));
