  ctx.fillStyle = '#A28F84'; ctx.fill();
  ctx.beginPath(); ctx.moveTo(145, 648);
  ctx.bezierCurveTo(400, 663, 630, 631, 950, 651);
  ctx.bezierCurveTo(1110, 662, 1270, 637, 1430, 645);
  ctx.lineTo(1430, 795); ctx.lineTo(145, 795); ctx.closePath();
  ctx.fillStyle = '#71616B'; ctx.fill();
  const chips = [[196,530],[487,520],[827,525],[1095,522],[1410,518],[220,600],[450,610],
    [690,612],[950,595],[1110,615],[1400,601],[200,700],[520,675],[900,679],[1140,672],[1400,685]];
  for (let i = 0; i < chips.length; i++) {
    const p = chips[i], w = 13+(i%3)*4;
    polygon([[p[0]-w, p[1]], [p[0]-w*.35,p[1]-4], [p[0]+w,p[1]-1], [p[0]+w*.6,p[1]+4]],
            i<5 ? '#B2A49B' : (i<11 ? '#8E7C74' : '#62535F'));
  }

  // The reservoir is porous rock, without a halo, blur, or changing silhouette.
  ctx.beginPath(); ctx.moveTo(267, 731);
  ctx.bezierCurveTo(286, 696, 410, 693, 528, 708);
  ctx.bezierCurveTo(674, 677, 854, 699, 1018, 706);
  ctx.bezierCurveTo(1152, 686, 1371, 695, 1402, 730);
  ctx.bezierCurveTo(1420, 767, 1265, 782, 1093, 766);
  ctx.bezierCurveTo(889, 789, 705, 767, 542, 775);
  ctx.bezierCurveTo(383, 783, 256, 767, 267, 731); ctx.closePath();
  ctx.fillStyle = '#A66E50'; ctx.fill(); ctx.strokeStyle = '#D3A17A'; ctx.lineWidth = 1.7; ctx.stroke();
  const heatColor = ctx.createLinearGradient(330, 0, 1370, 0);
  heatColor.addColorStop(0, '#E7AA4C'); heatColor.addColorStop(.5, '#C6A28D'); heatColor.addColorStop(1, '#749CCB');
  for (let i = 0; i < 3; i++) {
    const y = 718+i*20;
    const route = curveRoute([1370, 738], [[1190,y-12, 1100,y+11, 950,y], [760,y-7, 520,y+12, 330,738]]);
    line(route.samples, '#885E4B', 9);
    line(route.samples, heatColor, 4.7);
    tracers(route, flowPhase*.6+i*.15, 7, i===0 ? '#E4BD8B' : '#D2B29B', 1.8, 17);
  }
  ctx.restore();
  polygon([[145, 500], [1430, 500], [1430, 795], [145, 795]], null, C.ink, 1.6);
  line([[154, 507], [1422, 507]], '#E0D9D1', 1.5);

  // Reinjection header is a deliberate underground manifold, separate from production.
  pipe([[600, 462], [600, 542], [1370, 542], [1370, 738]], 26, '#365E98', flowPhase+.22, 9, '#9BBADB', 22);
  pipe([[1210, 485], [1210, 542]], 26, '#365E98', flowPhase+.57, 2, '#9BBADB', 18);
  ellipse(1210, 542, 14, 8, null, C.steel, 1.6);
  pipe([[330, 738], [330, 350], [550, 350]], 32, '#B9753B', flowPhase, 7, '#EBC28B', 28);
  // Well casings and wellhead collars remain rigid and attached to their pipes.
  for (let i = 0; i < 2; i++) {
