  polygon([[550,415],[650,415],[615,465],[585,465]],vessel,C.ink,1.5);
  ctx.fillStyle=vessel; ctx.fillRect(550,245,100,170);
  ellipse(600,415,50,13,vessel,C.ink,1.4);
  line([[550,245],[550,415]],C.ink,1.5); line([[650,245],[650,415]],C.ink,1.5);
  ellipse(600,245,50,15,C.silver,C.ink,1.5);
  label('SEPARATOR',600,270,86,11,C.ink,'center');
  roundRect(578,291,44,105,7,C.navy,C.ink,1.2);
  ctx.save(); roundedPath(583,296,34,95,4); ctx.clip();
  ctx.fillStyle='#B77B48'; ctx.fillRect(583,343,34,48);
  for(let i=0;i<4;i++) {
    const u=((phase*5+i/4)%1+1)%1;
    const r=2.5*Math.pow(Math.sin(Math.PI*u),2);
    if(r>.02) circle(591+(i%2)*15,380-u*77,r,'#C7D5E7');
  }
  line([[584,343],[616,343]],'#E4B988',1.3);
  ctx.restore();
  circle(550,350,7,C.ink,C.steel,1.4); circle(550,350,3,'#E2AF6D');
  flange(600,458,26,Math.PI/2);

  // Steam supply and turbine exhaust have distinct, separated overhead corridors.
  pipe([[600,230],[600,205],[800,205],[800,285]],30,'#6D667F',flowPhase+.1,5,'#DCE3F1',20);
  pipe([[858,311],[882,311],[882,231],[1108,231],[1108,340],[1140,340]],28,'#657B9D',flowPhase+.43,6,'#C6D5E7',20);
  flange(701,205,30,0); flange(1000,231,28,0);

  // Rotor and generator have a fixed, common horizontal shaft.
  roundRect(835,343,108,14,2,C.side,C.ink,1.3);
  line([[838,347],[940,347]],C.white,1.8);
  roundRect(788,411,24,70,2,C.side,C.ink,1.3);
  roundRect(773,480,54,7,2,C.steel,C.ink,1.3);
  generator(940,350,100,54,spin,485,'GEN');
  turbineCasing(800,350,65,spin,true);
  flange(800,279,30,Math.PI/2);

  // Condenser face: two independent fan windows, a fixed coolant coil and a return port.
  enclosure(1140,285,140,200,24);
  label('CONDENSER',1210,304,112,11,C.ink,'center');
  for(let i=0;i<2;i++) {
    const x=1180+i*60;
    circle(x,350,24,C.navy,C.ink,1.3);
    ctx.save(); ctx.translate(x,350); runner(18,angle*12+i*.4,5,C.steel); ctx.restore();
  }
  roundRect(1155,397,110,58,4,C.navy,C.ink,1.1);
  const coil=makeRoute([[1168,408],[1253,408],[1253,420],[1168,420],[1168,432],[1253,432],[1253,444],[1168,444]],5);
  line(coil.samples,'#6588B6',4.2);
  tracers(coil,flowPhase+.35,5,'#C0D1E6',1.6,10);
  circle(1140,340,6.5,C.ink,C.steel,1.3); circle(1140,340,2.7,'#B5C7DE');
  circle(1210,485,6,C.ink,C.steel,1.3); circle(1210,485,2.5,C.blueLight);
  bolt(1150,475); bolt(1270,475);

  ctx.restore();
}

/**
 * Concept 01 - Solar Array / Precision Energy Flow
 * 25 seconds | one continuous scene | seamless loop | 16:9 UHD.
 * Pure Canvas 2D; no assets, runtime dependencies, glow, or frame accumulation.
 * time is supplied in SECONDS by Prysm Motion Studio.
 * Video export target: 100,000,000 bits/second (100 Mbps), set in the renderer.
 * This drawing function does not create or encode a video stream.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1600, height / 900, minSide / 900);
  const tau = Math.PI * 2;
  const phase = (currentScene + sceneProgress) / sceneCount;
  const angle = tau * phase;
  const flowPhase = 5 * loopT / duration;
  const C = {
    ink: '#17253E', navy: '#243B61', blue: '#365E98', blueLight: '#85A5CF',
    white: '#F5F7FC', silver: '#E3E9F3', steel: '#B6C2D4', side: '#8F9EB6',
    darkSteel: '#657894', amber: '#E7AA4C', copper: '#B97436', muted: '#CAD4E4'
  };

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.translate((width - 1600 * scale) * 0.5, (height - 900 * scale) * 0.5);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  function polygon(points, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function roundedPath(x, y, w, h, radius) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function roundRect(x, y, w, h, radius, fill, stroke, lineWidth) {
    roundedPath(x, y, w, h, radius);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function line(points, color, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function circle(x, y, radius, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, tau);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.3; ctx.stroke(); }
  }

  function label(text, x, y, maxWidth, size, color, align) {
    ctx.save();
    let fontSize = size;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    const measured = ctx.measureText(text).width;
    if (measured > maxWidth) fontSize *= maxWidth / measured;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function bolt(x, y, r) {
    circle(x, y, r || 2.1, C.darkSteel);
    line([[x - 0.8, y], [x + 0.8, y]], C.silver, 0.8);
  }

  function lightning(x, y, size, color) {
    polygon([
      [x + size * 0.08, y - size * 0.5], [x - size * 0.34, y + size * 0.05],
      [x - size * 0.03, y + size * 0.05], [x - size * 0.13, y + size * 0.5],
      [x + size * 0.34, y - size * 0.1], [x + size * 0.04, y - size * 0.1]
    ], color);
  }

  // Tangent-continuous cable corners, sampled once per cable per frame.
  function makeRoute(points, radius) {
    const samples = [points[0]];
    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1], b = points[i], c = points[i + 1];
      const da = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const db = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const r = Math.min(radius, da * 0.45, db * 0.45);
      const enter = [b[0] + (a[0] - b[0]) * r / da, b[1] + (a[1] - b[1]) * r / da];
      const leave = [b[0] + (c[0] - b[0]) * r / db, b[1] + (c[1] - b[1]) * r / db];
      samples.push(enter);
      for (let k = 1; k <= 10; k++) {
        const u = k / 10, v = 1 - u;
        samples.push([v * v * enter[0] + 2 * v * u * b[0] + u * u * leave[0],
                      v * v * enter[1] + 2 * v * u * b[1] + u * u * leave[1]]);
      }
    }
    samples.push(points[points.length - 1]);
    const lengths = [0];
    for (let i = 1; i < samples.length; i++) {
      lengths.push(lengths[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, lengths: lengths, total: lengths[lengths.length - 1] };
  }

  function routePoint(route, distance) {
    const d = Math.max(0, Math.min(route.total, distance));
    for (let i = 1; i < route.samples.length; i++) {
      if (d <= route.lengths[i]) {
        const a = route.samples[i - 1], b = route.samples[i];
        const u = (d - route.lengths[i - 1]) / Math.max(0.0001, route.lengths[i] - route.lengths[i - 1]);
        return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u];
      }
    }
    return route.samples[route.samples.length - 1];
  }

  function cable(points, cableWidth, cycle, count) {
    const route = makeRoute(points, 11);
    line(route.samples, C.ink, cableWidth);
    line(route.samples, C.darkSteel, Math.max(1, cableWidth - 3));
    for (let i = 0; i < count; i++) {
      const u = ((cycle + i / count) % 1 + 1) % 1;
      const envelope = Math.pow(Math.sin(Math.PI * u), 2);
      const half = Math.min(13 * envelope, u * route.total, (1 - u) * route.total);
      if (half < 0.02) continue;
      const trail = [];
      for (let k = 0; k <= 10; k++) trail.push(routePoint(route, u * route.total - half + 2 * half * k / 10));
      line(trail, C.amber, cableWidth * 0.42);
    }
  }

  function enclosure(x, y, w, h, depth) {
    const dx = depth, dy = -depth * 0.58;
    polygon([[x, y], [x + dx, y + dy], [x + w + dx, y + dy], [x + w, y]], C.white, C.ink);
    polygon([[x + w, y], [x + w + dx, y + dy], [x + w + dx, y + h + dy], [x + w, y + h]], C.side, C.ink);
    const metal = ctx.createLinearGradient(x, y, x + w, y);
    metal.addColorStop(0, C.white);
    metal.addColorStop(0.55, C.silver);
    metal.addColorStop(1, '#D2DBE9');
    roundRect(x, y, w, h, 5, metal, C.ink, 1.7);
    line([[x + 6, y + 10], [x + 6, y + h - 10]], C.white, 2);
    line([[x + w + dx * 0.48, y + dy * 0.48 + 12], [x + w + dx * 0.48, y + h + dy * 0.48 - 12]], C.darkSteel, 1);
  }

  // Uniform composition fit: a centered assembly with generous, equal margins.
  ctx.translate(-91.5, -105.4);
  ctx.scale(1.06, 1.06);
  // Fixed axonometric camera. Panel racks and their legs share world anchors.
  function project(u, v, z) {
    return [545 + 0.86 * (u - v), 325 + 0.44 * (u + v) - z];
  }

  function box(u, v, z, w, d, h, top, front, side) {
    const a = project(u, v, z + h), b = project(u + w, v, z + h);
    const c = project(u + w, v + d, z + h), e = project(u, v + d, z + h);
    polygon([b, c, project(u + w, v + d, z), project(u + w, v, z)], side, C.ink, 1.1);
    polygon([e, c, project(u + w, v + d, z), project(u, v + d, z)], front, C.ink, 1.1);
    polygon([a, b, c, e], top, C.ink, 1.1);
  }

  box(0, 0, -20, 565, 410, 20, '#DFE6F1', '#AAB8CD', '#8F9FB8');
  // Thin inset perimeter stays on the platform, away from the key background.
  line([project(13, 13, 0.7), project(552, 13, 0.7), project(552, 397, 0.7),
        project(13, 397, 0.7), project(13, 13, 0.7)], '#B3C0D5', 1.25);

  cable([project(543, 336, 2), project(543, 24, 2)], 6.2, flowPhase, 4);
  for (let row = 0; row < 3; row++) {
    const v = 20 + row * 140;
    const points = [project(514, v + 36, 2), project(543, v + 36, 2)];
    cable(points, 5.6, flowPhase + row / 3, 1);
  }
  // Collector and an exposed, restrained cable bridge to the inverter.
  box(529, 9, 0, 26, 30, 13, C.white, C.steel, C.side);
  cable([project(555, 24, 7), [1046, 596], [1065, 596], [1065, 559], [1120, 559]],
        9, flowPhase + 0.12, 3);

  const racks = [];
  for (let row = 0; row < 3; row++) {
    for (let col = 0; col < 3; col++) racks.push({ u: 22 + col * 180, v: 20 + row * 140, row: row, col: col });
  }
  racks.sort(function(a, b) { return a.u + a.v - b.u - b.v; });

  function rack(item) {
    const u = item.u, v = item.v, w = 150, d = 72;
    const rear = 68, drop = 28;
    function p(a, b, thickness) { return project(u + a, v + b, rear - drop * b / d - (thickness || 0)); }

    // Four separate feet and diagonal braces; no floating panel corners.
    const feet = [[12, 8], [134, 8], [12, 64], [134, 64]];
    for (let i = 0; i < feet.length; i++) {
      const a = feet[i][0], b = feet[i][1], h = rear - drop * b / d - 6;
      box(u + a - 3, v + b - 3, 0, 6, 6, h, C.silver, C.side, C.darkSteel);
    }
    line([project(u + 12, v + 64, 8), p(134, 64, 6)], C.darkSteel, 2.2);
    polygon([p(w, 0), p(w, d), p(w, d, 5), p(w, 0, 5)], C.side, C.ink, 1.2);
    polygon([p(0, d), p(w, d), p(w, d, 5), p(0, d, 5)], C.steel, C.ink, 1.2);

    const a = p(0, 0), b = p(w, 0), c = p(0, d);
    ctx.save();
    ctx.transform((b[0] - a[0]) / w, (b[1] - a[1]) / w,
                  (c[0] - a[0]) / d, (c[1] - a[1]) / d, a[0], a[1]);
    roundRect(0, 0, w, d, 2.2, C.silver, C.ink, 1.5);
    roundRect(3, 3, w - 6, d - 6, 0.8, '#183358');

    const cellW = 21.5, cellH = 20;
    for (let yy = 0; yy < 3; yy++) {
      for (let xx = 0; xx < 6; xx++) {
        const x = 4.5 + xx * 23.8, y = 4.5 + yy * 21.4;
        ctx.fillStyle = (xx + yy) % 2 === 0 ? '#2D548A' : '#254A7E';
        ctx.fillRect(x, y, cellW, cellH);
        line([[x + 0.6, y + 0.8], [x + cellW - 0.6, y + 0.8]], '#6584AF', 0.65);
        line([[x + 7.2, y + 1], [x + 7.2, y + cellH - 1]], '#8AA6CC', 0.55);
        line([[x + 14.3, y + 1], [x + 14.3, y + cellH - 1]], '#8AA6CC', 0.55);
      }
    }
    // A matte blue reflection is clipped entirely inside the opaque panel.
    ctx.save();
    roundedPath(3, 3, w - 6, d - 6, 0.8);
    ctx.clip();
    const sweep = 75 + 105 * Math.sin(angle + item.col * 0.26 + item.row * 0.34);
    const reflection = ctx.createLinearGradient(sweep - 30, 0, sweep + 30, 0);
    reflection.addColorStop(0, 'rgba(157,184,224,0)');
    reflection.addColorStop(0.5, 'rgba(157,184,224,0.17)');
    reflection.addColorStop(1, 'rgba(157,184,224,0)');
    ctx.fillStyle = reflection;
    ctx.fillRect(3, 3, w - 6, d - 6);
    ctx.restore();
    for (let k = 0; k < 2; k++) {
      bolt(1.6 + k * (w - 3.2), 1.6, 0.7);
      bolt(1.6 + k * (w - 3.2), d - 1.6, 0.7);
    }
    ctx.restore();
  }
  for (let i = 0; i < racks.length; i++) rack(racks[i]);

  // Equipment platform: opaque faces only, with no shadow on the chroma field.
  polygon([[1080, 574], [1430, 574], [1490, 635], [1140, 635]], '#DDE5F1', C.ink, 1.5);
  polygon([[1140, 635], [1490, 635], [1490, 655], [1140, 655]], '#9EADC4', C.ink, 1.5);
  polygon([[1080, 574], [1140, 635], [1140, 655], [1080, 594]], '#B8C5D8', C.ink, 1.5);
  cable([[1262, 548], [1274, 548], [1274, 576], [1320, 576]], 8, flowPhase + 0.46, 2);

  enclosure(1120, 407, 116, 208, 26);
  label('INVERTER', 1178, 425, 91, 12, C.ink, 'center');
  roundRect(1135, 443, 86, 57, 5, C.navy, C.ink);
  // A waveform moves inside its display; its ends are clipped and periodic.
  ctx.save();
  roundedPath(1142, 450, 72, 43, 2);
  ctx.clip();
  line([[1142, 472], [1214, 472]], '#527098', 0.8);
  const wave = [];
  for (let k = 0; k <= 72; k += 2) {
    wave.push([1142 + k, 472 + 10 * Math.sin(tau * k / 38 - 4 * angle)]);
  }
  line(wave, C.silver, 1.7);
  ctx.restore();
  for (let i = 0; i < 5; i++) {
    roundRect(1140, 517 + i * 6, 75, 2.3, 1.1, C.side);
  }
  circle(1178, 581, 16, C.ink, C.darkSteel);
  ctx.save();
  ctx.translate(1178, 581);
  ctx.rotate(angle * 12);
  for (let i = 0; i < 5; i++) {
    ctx.save(); ctx.rotate(i * tau / 5);
    polygon([[-2, -4], [-4, -11], [1, -13], [5, -7], [3, -3]], C.steel);
    ctx.restore();
  }
  ctx.restore();
  circle(1178, 581, 4, C.darkSteel, C.silver, 0.8);
  circle(1120, 559, 7, C.ink, C.steel, 1.5);
  circle(1120, 559, 2.8, C.amber);
  circle(1262, 548, 6, C.ink, C.steel);
  circle(1262, 548, 2.5, C.amber);
  bolt(1130, 605); bolt(1226, 605);

  enclosure(1320, 333, 120, 282, 26);
  label('STORAGE', 1380, 354, 95, 12, C.ink, 'center');
  for (let i = 0; i < 4; i++) {
    const y = 376 + i * 42;
    roundRect(1333, y, 94, 33, 4, '#CAD4E4', C.side, 1);
    roundRect(1343, y + 10, 54, 13, 2.3, C.navy);
    for (let k = 0; k < 5; k++) {
      const amount = 0.5 + 0.5 * Math.sin(angle * 2 - i * 0.8 - k * 0.36);
      ctx.fillStyle = 'rgb(' + Math.round(163 + amount * 68) + ',' + Math.round(123 + amount * 47) + ',' + Math.round(66 + amount * 10) + ')';
      ctx.fillRect(1346 + k * 9.3, y + 13, 6.2, 7);
    }
    line([[1409, y + 12], [1418, y + 12]], C.darkSteel, 1.5);
    line([[1409, y + 20], [1418, y + 20]], C.darkSteel, 1.5);
  }
  circle(1380, 573, 16, C.navy);
  lightning(1380, 573, 21, C.amber);
  circle(1320, 576, 6, C.ink, C.steel);
  circle(1320, 576, 2.5, C.amber);
  bolt(1330, 605); bolt(1430, 605);

  ctx.restore();
}

/**
 * Concept 02 - Wind Farm / Synchronized Turbine Network
 * 25 seconds | one continuous scene | seamless loop | 16:9 UHD.
 * Pure Canvas 2D; no assets, runtime dependencies, glow, or frame accumulation.
 * time is supplied in SECONDS by Prysm Motion Studio.
 * Video export target: 100,000,000 bits/second (100 Mbps), set in the renderer.
 * This drawing function does not create or encode a video stream.
 */
function draw(ctx, time, width, height) {
  ctx.fillStyle = '#00FF00';
  ctx.fillRect(0, 0, width, height);
  const t = time;
  const duration = 25;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const scale = Math.min(width / 1600, height / 900, minSide / 900);
  const tau = Math.PI * 2;
  const phase = (currentScene + sceneProgress) / sceneCount;
  const angle = tau * phase;
  const flowPhase = 5 * loopT / duration;
  const C = {
    ink: '#17253E', navy: '#243B61', blue: '#365E98', blueLight: '#85A5CF',
    white: '#F5F7FC', silver: '#E3E9F3', steel: '#B6C2D4', side: '#8F9EB6',
    darkSteel: '#657894', amber: '#E7AA4C', copper: '#B97436', muted: '#CAD4E4'
  };

  ctx.save();
  ctx.globalAlpha = 1;
  ctx.globalCompositeOperation = 'source-over';
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.translate((width - 1600 * scale) * 0.5, (height - 900 * scale) * 0.5);
  ctx.scale(scale, scale);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  function polygon(points, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath();
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function roundedPath(x, y, w, h, radius) {
    const r = Math.min(radius, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function roundRect(x, y, w, h, radius, fill, stroke, lineWidth) {
    roundedPath(x, y, w, h, radius);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.4; ctx.stroke(); }
  }

  function line(points, color, lineWidth) {
    ctx.beginPath();
    ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.strokeStyle = color;
    ctx.lineWidth = lineWidth;
    ctx.stroke();
  }

  function circle(x, y, radius, fill, stroke, lineWidth) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, tau);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lineWidth || 1.3; ctx.stroke(); }
  }

  function label(text, x, y, maxWidth, size, color, align) {
    ctx.save();
    let fontSize = size;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    const measured = ctx.measureText(text).width;
    if (measured > maxWidth) fontSize *= maxWidth / measured;
    ctx.font = '600 ' + fontSize + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = align || 'left';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    ctx.fillText(text, x, y);
    ctx.restore();
  }

  function bolt(x, y, r) {
    circle(x, y, r || 2.1, C.darkSteel);
    line([[x - 0.8, y], [x + 0.8, y]], C.silver, 0.8);
  }

  function lightning(x, y, size, color) {
    polygon([
      [x + size * 0.08, y - size * 0.5], [x - size * 0.34, y + size * 0.05],
      [x - size * 0.03, y + size * 0.05], [x - size * 0.13, y + size * 0.5],
      [x + size * 0.34, y - size * 0.1], [x + size * 0.04, y - size * 0.1]
    ], color);
  }

  // Tangent-continuous cable corners, sampled once per cable per frame.
  function makeRoute(points, radius) {
    const samples = [points[0]];
    for (let i = 1; i < points.length - 1; i++) {
      const a = points[i - 1], b = points[i], c = points[i + 1];
      const da = Math.hypot(b[0] - a[0], b[1] - a[1]);
      const db = Math.hypot(c[0] - b[0], c[1] - b[1]);
      const r = Math.min(radius, da * 0.45, db * 0.45);
      const enter = [b[0] + (a[0] - b[0]) * r / da, b[1] + (a[1] - b[1]) * r / da];
      const leave = [b[0] + (c[0] - b[0]) * r / db, b[1] + (c[1] - b[1]) * r / db];
      samples.push(enter);
      for (let k = 1; k <= 10; k++) {
        const u = k / 10, v = 1 - u;
        samples.push([v * v * enter[0] + 2 * v * u * b[0] + u * u * leave[0],
                      v * v * enter[1] + 2 * v * u * b[1] + u * u * leave[1]]);
      }
    }
    samples.push(points[points.length - 1]);
    const lengths = [0];
    for (let i = 1; i < samples.length; i++) {
      lengths.push(lengths[i - 1] + Math.hypot(samples[i][0] - samples[i - 1][0], samples[i][1] - samples[i - 1][1]));
    }
    return { samples: samples, lengths: lengths, total: lengths[lengths.length - 1] };
  }

  function routePoint(route, distance) {
    const d = Math.max(0, Math.min(route.total, distance));
    for (let i = 1; i < route.samples.length; i++) {
      if (d <= route.lengths[i]) {
        const a = route.samples[i - 1], b = route.samples[i];
        const u = (d - route.lengths[i - 1]) / Math.max(0.0001, route.lengths[i] - route.lengths[i - 1]);
        return [a[0] + (b[0] - a[0]) * u, a[1] + (b[1] - a[1]) * u];
      }
    }
    return route.samples[route.samples.length - 1];
  }

  function cable(points, cableWidth, cycle, count) {
    const route = makeRoute(points, 11);
    line(route.samples, C.ink, cableWidth);
    line(route.samples, C.darkSteel, Math.max(1, cableWidth - 3));
    for (let i = 0; i < count; i++) {
      const u = ((cycle + i / count) % 1 + 1) % 1;
      const envelope = Math.pow(Math.sin(Math.PI * u), 2);
      const half = Math.min(13 * envelope, u * route.total, (1 - u) * route.total);
      if (half < 0.02) continue;
      const trail = [];
      for (let k = 0; k <= 10; k++) trail.push(routePoint(route, u * route.total - half + 2 * half * k / 10));
      line(trail, C.amber, cableWidth * 0.42);
    }
  }

  function enclosure(x, y, w, h, depth) {
    const dx = depth, dy = -depth * 0.58;
    polygon([[x, y], [x + dx, y + dy], [x + w + dx, y + dy], [x + w, y]], C.white, C.ink);
    polygon([[x + w, y], [x + w + dx, y + dy], [x + w + dx, y + h + dy], [x + w, y + h]], C.side, C.ink);
    const metal = ctx.createLinearGradient(x, y, x + w, y);
    metal.addColorStop(0, C.white);
    metal.addColorStop(0.55, C.silver);
    metal.addColorStop(1, '#D2DBE9');
    roundRect(x, y, w, h, 5, metal, C.ink, 1.7);
    line([[x + 6, y + 10], [x + 6, y + h - 10]], C.white, 2);
    line([[x + w + dx * 0.48, y + dy * 0.48 + 12], [x + w + dx * 0.48, y + h + dy * 0.48 - 12]], C.darkSteel, 1);
  }

  // Complete swept discs remain separate: 425-unit hub spacing, radii 137/173.
  const turbines = [
    { x: 375, y: 316, r: 137, bottom: 665, base: 33, turns: 6, offset: 0.12 },
    { x: 800, y: 262, r: 173, bottom: 708, base: 43, turns: 5, offset: 0.03 },
    { x: 1225, y: 316, r: 137, bottom: 665, base: 33, turns: 6, offset: 0.29 }
  ];

  // Three independent routes terminate at three physical substation ports.
  cable([[375, 680], [375, 733], [655, 733], [655, 790], [688, 790]], 9, flowPhase + 0.1, 3);
  cable([[800, 726], [800, 742]], 8, flowPhase + 0.4, 1);
  cable([[1225, 680], [1225, 733], [967, 733], [967, 790], [934, 790]], 9, flowPhase + 0.7, 3);

  function foundation(x, bottom, width) {
    const w = width * 1.65;
    polygon([[x - w, bottom + 3], [x - w * 0.7, bottom - 9], [x + w * 0.7, bottom - 9],
             [x + w, bottom + 3], [x + w * 0.68, bottom + 17], [x - w * 0.68, bottom + 17]], C.silver, C.ink, 1.5);
    polygon([[x - w * 0.68, bottom + 17], [x + w * 0.68, bottom + 17],
             [x + w * 0.68, bottom + 25], [x - w * 0.68, bottom + 25]], C.side, C.ink, 1.3);
    for (let k = -1; k <= 1; k += 2) {
      bolt(x + k * w * 0.72, bottom + 3, 2.4);
      bolt(x + k * w * 0.4, bottom + 12, 2.2);
    }
  }

  function blade(radius) {
    ctx.beginPath();
    ctx.moveTo(-0.027 * radius, -0.075 * radius);
    ctx.bezierCurveTo(-0.055 * radius, -0.18 * radius, -0.061 * radius, -0.30 * radius, -0.041 * radius, -0.48 * radius);
    ctx.bezierCurveTo(-0.024 * radius, -0.67 * radius, -0.009 * radius, -0.91 * radius, 0.008 * radius, -0.993 * radius);
    ctx.bezierCurveTo(0.013 * radius, -1.002 * radius, 0.028 * radius, -1.001 * radius, 0.029 * radius, -0.984 * radius);
    ctx.bezierCurveTo(0.033 * radius, -0.85 * radius, 0.084 * radius, -0.51 * radius, 0.091 * radius, -0.35 * radius);
    ctx.bezierCurveTo(0.096 * radius, -0.23 * radius, 0.056 * radius, -0.135 * radius, 0.029 * radius, -0.075 * radius);
    ctx.closePath();
    const material = ctx.createLinearGradient(-0.05 * radius, 0, 0.09 * radius, 0);
    material.addColorStop(0, '#BBC8DC');
    material.addColorStop(0.38, '#F8FAFD');
    material.addColorStop(1, '#D8E1EF');
    ctx.fillStyle = material;
    ctx.fill();
    ctx.strokeStyle = C.ink;
    ctx.lineWidth = 1.25;
    ctx.stroke();
    // A narrow leading-edge seam stays attached to each rigid blade.
    ctx.beginPath();
    ctx.moveTo(-0.012 * radius, -0.19 * radius);
    ctx.bezierCurveTo(-0.025 * radius, -0.40 * radius, 0.002 * radius, -0.72 * radius, 0.013 * radius, -0.93 * radius);
    ctx.strokeStyle = '#8B9DB9';
    ctx.lineWidth = 0.95;
    ctx.stroke();
  }

  function turbine(item) {
    const x = item.x, y = item.y, bottom = item.bottom, half = item.base * 0.5;
    foundation(x, bottom, item.base);
    // The mast is rigid; only the rotor rotates around the fixed hub.
    const mast = ctx.createLinearGradient(x - half, 0, x + half, 0);
    mast.addColorStop(0, '#B6C4D9');
    mast.addColorStop(0.38, C.white);
    mast.addColorStop(0.66, C.silver);
    mast.addColorStop(1, '#9DAEC7');
    polygon([[x - 8.5, y + 4], [x + 8.5, y + 4], [x + half, bottom + 6], [x - half, bottom + 6]], mast, C.ink, 1.65);
    for (let i = 1; i <= 3; i++) {
      const yy = y + (bottom - y) * i / 4;
      const localHalf = 8.5 + (half - 8.5) * (yy - y) / (bottom - y);
      line([[x - localHalf + 1, yy], [x + localHalf - 1, yy]], '#A7B6CD', 0.9);
    }
    roundRect(x - 7, bottom - 48, 14, 38, 4, '#A6B6CD', C.darkSteel, 1);
    line([[x + 3.5, bottom - 32], [x + 3.5, bottom - 26]], C.ink, 1.3);

    // Nacelle, rear housing, ventilation, and a front bearing behind the rotor.
    roundRect(x - 29, y - 15, 66, 30, 9, C.steel, C.ink, 1.5);
    line([[x + 22, y - 8], [x + 31, y - 8]], C.darkSteel, 1.1);
    line([[x + 22, y - 3], [x + 31, y - 3]], C.darkSteel, 1.1);
    circle(x, y, item.r * 0.115, C.darkSteel, C.ink, 1.3);

    const rotorAngle = tau * (phase * item.turns + item.offset);
    for (let i = 0; i < 3; i++) {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(rotorAngle + i * tau / 3);
      blade(item.r);
      ctx.restore();
    }
    const hub = ctx.createLinearGradient(x - 15, y - 15, x + 15, y + 15);
    hub.addColorStop(0, C.white);
    hub.addColorStop(0.6, C.silver);
    hub.addColorStop(1, C.side);
    circle(x, y, item.r * 0.095, hub, C.ink, 1.5);
    circle(x, y, item.r * 0.035, C.steel, C.darkSteel, 0.9);
    // Three bearing bolts rotate with the assembly, without orbiting loosely.
    for (let i = 0; i < 3; i++) {
      const a = rotorAngle + i * tau / 3;
      circle(x + Math.sin(a) * item.r * 0.063, y - Math.cos(a) * item.r * 0.063, 1.45, C.darkSteel);
    }
  }
  for (let i = 0; i < turbines.length; i++) turbine(turbines[i]);

  enclosure(688, 756, 224, 72, 22);
  label('GRID CONTROL', 707, 770, 136, 11, C.ink);
  for (let i = 0; i < 3; i++) {
    const x = 707 + i * 64;
    roundRect(x, 785, 51, 28, 3, C.navy, C.ink, 1);
    for (let k = 0; k < 4; k++) {
      const h = 5 + 8 * (0.5 + 0.5 * Math.sin(angle * 3 - i * 0.9 - k * 0.45));
      roundRect(x + 7 + k * 10, 806 - h, 5, h, 1.2, C.amber);
    }
  }
  circle(688, 790, 6.2, C.ink, C.steel, 1.3);
  circle(688, 790, 2.6, C.amber);
  circle(934, 790, 6.2, C.ink, C.steel, 1.3);
  circle(934, 790, 2.6, C.amber);
  circle(800, 742, 4.8, C.ink, C.steel, 1.1);
  circle(800, 742, 2, C.amber);
  bolt(699, 819); bolt(900, 819);

  ctx.restore();
}
